INSERT INTO "public"."services" ("id", "created_at", "title", "description", "icon", "display_order") VALUES ('48c54a17-a7df-4141-8f26-0916431a0fe3', '2026-01-20 22:52:28.162601+00', 'Consultoria em TI e Estratégia', 'Transformo desafios tecnológicos em soluções estratégicas. Ofereço análise aprofundada, roadmap tecnológico e recomendações personalizadas para otimizar processos, impulsionar o crescimento e garantir a governança do seu negócio.', 'fa-solid fa-handshake', '2'), ('6e6cdaee-8b91-4b40-9dde-25eaae7c87d3', '2026-01-20 22:52:28.162601+00', 'Gestão Estratégica de Projetos', 'Ofereço assessoria especializada na gestão de projetos de TI, do planejamento à entrega. Garanto o cumprimento de prazos, a qualidade das entregas e o alinhamento estratégico com os objetivos do seu negócio, aplicando metodologias ágeis e tradicionais.', 'fa-solid fa-chart-line', '3'), ('b615d6d8-bd87-485d-a1b9-760a51d9aec7', '2026-01-20 22:52:28.162601+00', 'Liderança e Desenvolvimento de Equipes', 'Com 7 anos de experiência, lidero e motivo equipes multidisciplinares para o alcance de objetivos em ambientes de alta pressão. Foco no desenvolvimento de talentos, gestão de conflitos e promoção de um ambiente colaborativo e produtivo.', 'fa-solid fa-people-group', '5'), ('bcadfaf1-ba3b-48f2-af59-2fb76ee7f982', '2026-01-20 22:52:28.162601+00', 'Gestão de Riscos e Otimização de Processos', 'Estruturo e aprimoro planos de gestão de riscos, minimizando vulnerabilidades e garantindo a continuidade das operações. Identifico gargalos e proponho soluções para otimizar processos, aumentando a eficiência e reduzindo custos.', 'fa-solid fa-arrows-rotate', '4'), ('bd98a370-5131-44a8-8bfe-55abb14c44c6', '2026-01-20 22:52:28.162601+00', 'Desenvolvimento de Sistemas Personalizados', 'Desenvolvo sistemas web e mobile sob medida, do planejamento à entrega. Transformo suas ideias em soluções robustas, escaláveis e eficientes, utilizando tecnologias como Python, PHP, JavaScript e MySQL.', 'fa-solid fa-laptop-code', '3'), ('ed5c8df0-e29a-4a10-9f81-5e5d5b53aabe', '2026-01-20 22:52:28.162601+00', 'Arquitetura e Governança de Soluções', 'Crio o design e a estrutura de sistemas complexos, garantindo soluções robustas, escaláveis e seguras. Alinho as melhores práticas de mercado e governança de TI às necessidades específicas do seu projeto, incluindo Cloud (AWS/Azure).', 'fa-solid fa-sitemap', '2');